/* glyph_apps.h — programs built into a bare-metal kernel, shared by the
 * standalone Glyph kernel (glyph_os.c) and the inference-kernel REPL hook
 * (glyph_repl.c). The table itself is generated by tools/mkpayload.sh. */
#ifndef GLYPH_APPS_H
#define GLYPH_APPS_H

#include <stdint.h>

typedef struct glyph_payload {
    const char *name;     /* "examples/demo", "corpus/tc_sieve", ... */
    const char *src;
    const char *events;   /* event script used by the conformance run */
    uint32_t    len, elen;
    uint32_t    is_app;   /* an example: offered by the menu and by name */
    uint32_t    pad;
} glyph_payload;

extern const glyph_payload glyph_payloads[];
extern const uint32_t glyph_payload_count;

/* Console output through the kernel's console_write (COM1 + VGA). */
void glyph_apps_out(const char *s);
void glyph_apps_out_u32(uint32_t v);

/* Run every embedded program's event script and write the transcripts
 * between "=== GLYPH BEGIN name ===" / "=== GLYPH END name ===" markers,
 * then "=== GLYPH DONE n ===". */
void glyph_apps_conformance(void);

/* Index of the example called name (n bytes, without "examples/"), or -1. */
int glyph_apps_find(const char *name, uint64_t n);

/* Run an example interactively (VGA + PS/2/COM1) until ESC. */
int glyph_apps_run(int index);

/* Write "  name" lines for every example. */
void glyph_apps_list(void);

/* Index of the n-th example, or -1. */
int glyph_apps_nth(uint32_t n);

#endif
